import re

def parse_amounts(df):
    def convert_to_float(amount):
        if amount == "":
            return None
        # Remove dollar sign and commas
        cleaned_amount = re.sub(r'[$,]', '', amount)
        try:
            return float(cleaned_amount)
        except ValueError:
            return None

    df["Amount"] = [convert_to_float(a) for a in df["Amount"]]
    df["Amount"] = df["Amount"].astype(float, errors='ignore')
    return df

def win_rates(df):
    rates = {}
    for rep in sorted(df["Owner"].unique()):
        mine = df[df["Owner"] == rep]
        won = int((mine["Outcome"] == "won").sum())
        lost = int((mine["Outcome"] == "lost").sum())
        if won + lost > 0:
            rates[rep] = round(won / (won + lost), 4)
        else:
            rates[rep] = None
    return rates

